import { createFileRoute } from "@tanstack/react-router";

/**
 * POST /api/tts
 * Body: { text: string; voiceId?: string }
 * Returns: audio/mpeg generated by ElevenLabs (Arabic-friendly multilingual model).
 *
 * The endpoint is server-only — the API key never leaves the worker.
 */
export const Route = createFileRoute("/api/tts")({
  server: {
    handlers: {
      POST: async ({ request }) => {
        const apiKey = process.env.ELEVENLABS_API_KEY;
        if (!apiKey) {
          return new Response("ELEVENLABS_API_KEY not configured", { status: 500 });
        }

        let body: { text?: string; voiceId?: string };
        try { body = await request.json(); }
        catch { return new Response("Invalid JSON body", { status: 400 }); }

        const text = (body.text ?? "").toString().trim();
        if (!text || text.length > 800) {
          return new Response("Invalid text", { status: 400 });
        }

        // Sarah — natural, clear, multilingual-friendly default.
        const voiceId = (body.voiceId ?? "EXAVITQu4vr4xnSDxMaL").toString();

        const res = await fetch(
          `https://api.elevenlabs.io/v1/text-to-speech/${voiceId}?output_format=mp3_44100_128`,
          {
            method: "POST",
            headers: {
              "xi-api-key": apiKey,
              "Content-Type": "application/json",
            },
            body: JSON.stringify({
              text,
              model_id: "eleven_multilingual_v2",
              voice_settings: {
                stability: 0.55,
                similarity_boost: 0.8,
                style: 0.25,
                use_speaker_boost: true,
                speed: 1.0,
              },
            }),
          },
        );

        if (!res.ok) {
          const err = await res.text().catch(() => "");
          return new Response(err || `TTS failed: ${res.status}`, { status: 502 });
        }

        const audio = await res.arrayBuffer();
        return new Response(audio, {
          status: 200,
          headers: {
            "Content-Type": "audio/mpeg",
            "Cache-Control": "public, max-age=86400",
          },
        });
      },
    },
  },
});
